import test from'node:test';import assert from'node:assert/strict';import{matchNarrativeFactBundle}from'../../domain/match/matchNarrativeFactBundle.js';test('tous les faits détaillés reçoivent le même matchId',()=>{const b=matchNarrativeFactBundle({matchId:'m',decisions:[{choice:'A'}],events:[{text:'B'}]});assert.equal(b.decisions[0].matchId,'m');assert.equal(b.events[0].matchId,'m');});
